pub(super) fn content_config() -> String {
    format!(
        "{}{}{}{}{}{}{}",
        content_model_header(),
        agent_project_content_collections(),
        document_project::content_collections(),
        PROPOSAL_SBIR_COLLECTIONS,
        agent_project_content_relations(),
        document_project::content_relations(),
        PROPOSAL_SBIR_RELATIONS
    )
}

